-- txt2cad schema. SQLite dialect.
-- Run with:  PRAGMA foreign_keys = ON;  PRAGMA journal_mode = WAL;   (set on every connection)
--
-- Conventions
--  * ids: TEXT uuid, generated by the app (uuid4). The default below is a fallback only.
--  * times: TEXT, ISO-8601 UTC ending in 'Z'. A CHECK enforces the shape. Postgres move: timestamptz.
--  * json: TEXT with json_valid() CHECK. Postgres move: jsonb.
--  * booleans: INTEGER 0/1. Postgres move: boolean.
--  * owner_id: 'local' while the app is single-user. When auth arrives it becomes a real users(id) FK.
--    Every read and write goes through data-layer functions that take owner_id (see architecture.md, access rules).
--  * files (IFC, previews, run logs) live on disk under data/projects/<project_id>/ ; the db stores paths.

create table projects (
  id              text primary key default (lower(hex(randomblob(16)))),
  owner_id        text not null default 'local',
  name            text not null check (length(name) between 1 and 200),
  head_version_id text references versions(id) on delete set null deferrable initially deferred,
  created_at      text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
                  check (created_at like '____-__-__T%Z'),
  updated_at      text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
                  check (updated_at like '____-__-__T%Z')
);
create index projects_owner_updated on projects (owner_id, updated_at desc);

-- One row per finished version. History is linear. Revert appends a copy (mode = 'revert').
create table versions (
  id           text primary key default (lower(hex(randomblob(16)))),
  project_id   text not null references projects(id) on delete cascade,
  owner_id     text not null default 'local',
  number       integer not null check (number >= 1),
  parent_id    text references versions(id) on delete set null,
  mode         text not null check (mode in ('design','edit','ops','revert','import')),
  prompt       text not null default '',
  llm_label    text not null default '',                       -- "provider/model" at run time, for the record
  design_json  text not null check (json_valid(design_json)),  -- what the LLM built: levels, rooms, doors ...
  spec_json    text not null check (json_valid(spec_json)),    -- derived geometric IR: walls, slabs, openings ...
  guids_json   text not null default '{}' check (json_valid(guids_json)),  -- element id -> IFC GlobalId
  approach     text not null default '',
  notes_json   text not null default '[]' check (json_valid(notes_json)),
  summary      text not null default '',
  ifc_path     text not null,
  created_at   text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
               check (created_at like '____-__-__T%Z'),
  -- Optimistic concurrency lives here: two edits against the same base both try to insert number n+1.
  -- The second one hits this constraint and the API answers 409.
  unique (project_id, number)
);
create index versions_project_number on versions (project_id, number desc);
create index versions_parent on versions (parent_id);
create index versions_owner on versions (owner_id);

-- The checklist extracted from the prompt, and its checked status for a version.
create table requirements (
  id          text primary key default (lower(hex(randomblob(16)))),
  version_id  text not null references versions(id) on delete cascade,
  position    integer not null check (position >= 0),
  kind        text not null check (kind in (
                'storeys','room','room_level','area','adjacent','orientation','window','door','stair',
                'furniture','roof','feature','dimension','material','style','asset','structure','other')),
  params_json text not null default '{}' check (json_valid(params_json)),
  text        text not null,
  supported   integer not null default 1 check (supported in (0,1)),
  status      text not null default 'not_checked'
              check (status in ('met','unmet','unsupported','not_checked')),
  detail      text not null default '',
  unique (version_id, position)
);
create index requirements_version on requirements (version_id);

-- One row per prompt run (a run may fail and produce no version). Events are recorded to a .jsonl file for replay.
create table runs (
  id                text primary key default (lower(hex(randomblob(16)))),
  project_id        text not null references projects(id) on delete cascade,
  owner_id          text not null default 'local',
  base_version_id   text references versions(id) on delete set null,
  result_version_id text references versions(id) on delete set null,
  prompt            text not null,
  status            text not null default 'queued'
                    check (status in ('queued','running','succeeded','failed','cancelled')),
  error             text not null default '',
  llm_profile_id    text references llm_profiles(id) on delete set null,
  focus_element_id  text,                                       -- element selected in the viewer when the prompt was sent
  record_path       text,                                       -- runs/<id>.jsonl, the SSE event stream
  input_tokens      integer,
  output_tokens     integer,
  started_at        text check (started_at is null or started_at like '____-__-__T%Z'),
  finished_at       text check (finished_at is null or finished_at like '____-__-__T%Z'),
  created_at        text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
                    check (created_at like '____-__-__T%Z')
);
create index runs_project_created on runs (project_id, created_at desc);
create index runs_base_version on runs (base_version_id);
create index runs_result_version on runs (result_version_id);
create index runs_llm_profile on runs (llm_profile_id);
create index runs_status on runs (status);

-- Images attached to a prompt (sketch, site photo). Content-addressed so the same file is stored once.
create table attachments (
  id          text primary key default (lower(hex(randomblob(16)))),
  run_id      text not null references runs(id) on delete cascade,
  sha256      text not null check (length(sha256) = 64),
  filename    text not null,
  media_type  text not null check (media_type in ('image/png','image/jpeg','image/webp','image/gif')),
  size_bytes  integer not null check (size_bytes > 0 and size_bytes <= 10485760),   -- 10 MB cap
  path        text not null,
  created_at  text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
              check (created_at like '____-__-__T%Z'),
  unique (run_id, sha256)
);
create index attachments_run on attachments (run_id);

-- Generated deliverables, cached per version and format. Regenerated on demand if the file is missing.
create table exports (
  id            text primary key default (lower(hex(randomblob(16)))),
  version_id    text not null references versions(id) on delete cascade,
  format        text not null check (format in (
                  'ifc','dxf','svg',
                  'estimate_csv','review_md','spec_json','design_json')),
  path          text not null,
  sha256        text not null check (length(sha256) = 64),
  size_bytes    integer not null check (size_bytes >= 0),
  tool_version  text not null default '',                       -- e.g. "ezdxf 1.3.x", for reproducibility
  created_at    text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
                check (created_at like '____-__-__T%Z'),
  unique (version_id, format)
);

-- Which LLM to call. The key is never stored: api_key_env names an environment variable.
create table llm_profiles (
  id            text primary key default (lower(hex(randomblob(16)))),
  owner_id      text not null default 'local',
  name          text not null check (length(name) between 1 and 100),
  provider      text not null check (provider in ('mock','openai_compat')),
  base_url      text not null default '',
  model         text not null default '',
  api_key_env   text not null default '',
  options_json  text not null default '{}' check (json_valid(options_json)),   -- effort, vision on/off, timeouts
  is_default    integer not null default 0 check (is_default in (0,1)),
  created_at    text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
                check (created_at like '____-__-__T%Z'),
  updated_at    text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
                check (updated_at like '____-__-__T%Z'),
  unique (owner_id, name)
);
create unique index llm_profiles_one_default on llm_profiles (owner_id) where is_default = 1;

-- Phase D: parametric asset cards ("bricks"). Library cards are loaded from files; model-written and user-written ones are rows.
create table bricks (
  id              text primary key default (lower(hex(randomblob(16)))),
  owner_id        text not null default 'local',
  project_id      text references projects(id) on delete cascade,   -- null = available in every project
  brick_key       text not null check (brick_key glob '[a-z0-9_]*'),
  name            text not null,
  source          text not null check (source in ('model','user')),
  definition_json text not null check (json_valid(definition_json)),
  created_at      text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
                  check (created_at like '____-__-__T%Z')
);
create unique index bricks_unique_key on bricks (owner_id, coalesce(project_id, ''), brick_key);
create index bricks_project on bricks (project_id);

-- updated_at upkeep
create trigger projects_touch after update on projects
  when new.updated_at = old.updated_at
  begin update projects set updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') where id = new.id; end;
create trigger llm_profiles_touch after update on llm_profiles
  when new.updated_at = old.updated_at
  begin update llm_profiles set updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') where id = new.id; end;
